begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
update public.community_operations set enabled=true,enrollment=true,discovery=true,publish=true,engagement=true,cohort_required=false;
update public.community_feature_controls set enabled=true;
insert into auth.users(id,email) values('71000000-0000-4000-8000-000000000001','combined-lifecycle@mizyun.test');
update public.profiles set birth_year=1990 where id='71000000-0000-4000-8000-000000000001';
set local role authenticated;set local request.jwt.claim.role='authenticated';set local request.jwt.claim.sub='71000000-0000-4000-8000-000000000001';
select * from public.community_save_profile('combined_lifecycle','Combined','CL',null,false,true,'2026-09-30');
select * from public.community_messaging_rpc('preferences','{"enabled":true}');
select * from public.community_broader_discovery_rpc('preferences','{"enabled":true}');
select lives_ok($$select * from public.community_export_page('comments')$$,'Ordinary export chains comments');
select lives_ok($$select * from public.community_export_page('commentPreferences')$$,'Ordinary export chains comment preferences');
select lives_ok($$select * from public.community_export_page('commentMentions')$$,'Ordinary export chains mention inbox');
select lives_ok($$select * from public.community_export_page('groupMemberships')$$,'Ordinary export chains memberships');
select lives_ok($$select * from public.community_export_page('groupPosts')$$,'Ordinary export chains authored group posts');
select lives_ok($$select * from public.community_export_page('groupAppeals')$$,'Ordinary export chains own group appeals');
select lives_ok($$select * from public.community_export_page('groupEvents')$$,'Ordinary export chains group notifications');
select lives_ok($$select * from public.community_export_page('groupOperations')$$,'Ordinary export chains no-text group receipts');
select lives_ok($$select * from public.community_export_page('messages')$$,'Ordinary export chains authored messages');
select lives_ok($$select * from public.community_export_page('messageOperations')$$,'Ordinary export chains no-text message receipts');
select lives_ok($$select * from public.community_export_page('messagingPreferences')$$,'Ordinary export chains messaging choices');
select lives_ok($$select * from public.community_export_page('broaderDiscoveryPreferences')$$,'Ordinary export chains broader discovery choice');
select lives_ok($$select * from public.community_export_page('challenges')$$,'Ordinary export chains owned challenges');
select lives_ok($$select * from public.community_export_page('challengeContributions')$$,'Ordinary export chains deliberate contributions');
select lives_ok($$select * from public.community_export_page('mediaReviews')$$,'Ordinary export chains review notices');
reset role;set local request.jwt.claim.role='service_role';
insert into public.workouts(id,user_id,name,started_at,details) values('72000000-0000-4000-8000-000000000001','71000000-0000-4000-8000-000000000001','Independent private copy',now(),'{"workoutLifecycle":{"kind":"routine"}}');
insert into public.community_routine_shares(id,user_id,source_workout_id,source_updated_at,operation_id,enrollment_generation,snapshot) select ('73000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'71000000-0000-4000-8000-000000000001','72000000-0000-4000-8000-000000000001',now(),('74000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,1,'{"schemaVersion":"2026-10-01","title":"Deliberate public plan","exercises":[]}' from generate_series(1,3)n;
insert into public.community_routine_imports(user_id,share_id,workout_id,author_handle,snapshot,version) values('71000000-0000-4000-8000-000000000001','73000000-0000-4000-8000-000000000001','72000000-0000-4000-8000-000000000001','combined_lifecycle','{"title":"Deliberate public plan"}',1);
insert into public.community_media_assets(id,user_id,generation,operation_id,digest,alt_text,state) select ('75000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'71000000-0000-4000-8000-000000000001',1,('76000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,repeat('a',64),'Synthetic still','revoked' from generate_series(1,3)n;
insert into public.community_media_review_actions(user_id,asset_id,decision,reason) select '71000000-0000-4000-8000-000000000001','75000000-0000-4000-8000-000000000001','remove','Synthetic retained review notice' from generate_series(1,5);
set local role authenticated;set local request.jwt.claim.role='authenticated';
select is((select count(*) from public.community_export_page('routineShares')),3::bigint,'Ordinary export includes own shares through standalone hook');
select is((select count(*) from public.community_export_page('routineImports')),1::bigint,'Ordinary export includes own import attribution');
select is((select count(*) from public.community_export_page('media')),3::bigint,'Ordinary export includes own media through standalone hook');
select * from public.community_withdraw_profile();
select is((select count(*) from public.community_export_page('messagingPreferences')),0::bigint,'Withdrawal removes messaging enrollment choice');
select is((select count(*) from public.community_export_page('broaderDiscoveryPreferences')),0::bigint,'Withdrawal removes discovery enrollment choice');
reset role;set local request.jwt.claim.role='service_role';
select is((select complete from public.community_withdrawal_batch('71000000-0000-4000-8000-000000000001',1,1)),false,'One-item worker batch cannot complete with pending expansion artifacts');
select ok((select completed_at is null from public.community_withdrawal_jobs where user_id='71000000-0000-4000-8000-000000000001'),'Captured generation remains pending until expansion drain');
select * from public.community_withdrawal_batch('71000000-0000-4000-8000-000000000001',1,1);
select * from public.community_withdrawal_batch('71000000-0000-4000-8000-000000000001',1,1);
select is((select complete from public.community_withdrawal_batch('71000000-0000-4000-8000-000000000001',1,1)),false,'Remaining review notices prevent premature generation completion');
select is((select complete from public.community_withdrawal_batch('71000000-0000-4000-8000-000000000001',1,1)),true,'Resumed exact-generation drain completes');
select is((select count(*) from public.community_media_review_actions where user_id='71000000-0000-4000-8000-000000000001'),0::bigint,'Every review notice physically drained');
select is((select count(*) from public.community_routine_shares where user_id='71000000-0000-4000-8000-000000000001'),0::bigint,'All source shares physically drained');
select is((select count(*) from public.community_routine_imports where user_id='71000000-0000-4000-8000-000000000001'),0::bigint,'Import attribution physically drained');
select is((select count(*) from public.workouts where id='72000000-0000-4000-8000-000000000001'),1::bigint,'Community withdrawal preserves independent private workout');
select is((select count(*) from public.community_media_assets where user_id='71000000-0000-4000-8000-000000000001' and state<>'revoked'),0::bigint,'Media metadata becomes revoked before job completion');
select is((select count(*) from public.community_media_cleanup_jobs where user_id='71000000-0000-4000-8000-000000000001'),3::bigint,'Physical storage removals have durable retry tickets');
set local role authenticated;set local request.jwt.claim.role='authenticated';
select lives_ok($$select * from public.community_save_profile('combined_lifecycle','Fresh','FR',null,false,true,'2026-09-30')$$,'Fresh generation can enroll after complete drain');
select is((select result->>'enabled' from public.community_messaging_rpc('preferences')),'false','Fresh generation does not inherit messaging consent');
select is((select result->>'enabled' from public.community_broader_discovery_rpc('preferences')),'false','Fresh generation does not inherit discovery consent');
reset role;set local request.jwt.claim.role='service_role';
insert into public.community_media_assets(id,user_id,generation,operation_id,digest,alt_text,state) select ('78000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'71000000-0000-4000-8000-000000000001',2,('79000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,repeat('b',64),'Synthetic second generation','revoked' from generate_series(1,3)n;
insert into public.account_deletion_jobs(id,user_id,challenge_hash,status,stage,expires_at,worker_id,lease_expires_at) values('77000000-0000-4000-8000-000000000001','71000000-0000-4000-8000-000000000001','combined-synthetic-challenge','in_progress','auth',now()+interval '5 minutes','combined-worker',now()+interval '2 minutes');
select throws_ok($$select * from public.community_account_cleanup_batch('71000000-0000-4000-8000-000000000001','77000000-0000-4000-8000-000000000001','wrong-worker',1)$$,'P0001','community_access_denied','Expansion erasure rejects a stale worker lease');
select is((select complete from public.community_account_cleanup_batch('71000000-0000-4000-8000-000000000001','77000000-0000-4000-8000-000000000001','combined-worker',1)),false,'Account worker cannot complete while additional media metadata remains');
select * from public.community_account_cleanup_batch('71000000-0000-4000-8000-000000000001','77000000-0000-4000-8000-000000000001','combined-worker',1);
select is((select complete from public.community_account_cleanup_batch('71000000-0000-4000-8000-000000000001','77000000-0000-4000-8000-000000000001','combined-worker',1)),true,'Resumed bounded account worker drains expansion metadata before Auth erasure');
delete from auth.users where id='71000000-0000-4000-8000-000000000001';
select is((select count(*) from public.community_media_assets where user_id='71000000-0000-4000-8000-000000000001'),0::bigint,'Auth erasure removes media metadata');
select is((select count(*) from public.community_media_cleanup_jobs where user_id='71000000-0000-4000-8000-000000000001'),6::bigint,'Auth erasure cannot drop unacknowledged storage cleanup tickets');
select * from finish();rollback;
